<script setup lang="ts">
import {ref,watch,onUnmounted} from 'vue';import type {Scenario,Result} from '../types';import Worker from '../workers/sensitivity.worker?worker&inline';import {advise,amounts} from '../engine/advice';import {validate} from '../engine/cards';
const props=defineProps<{scenario:Scenario}>();let worker:InstanceType<typeof Worker>|null=null;const busy=ref(false),error=ref(''),rows=ref<{name:string;result:Result}[]>([]);const names:Record<string,string>={random:'全部随机',tight:'强牌示例',broad:'较宽示例'};
function cancel(){worker?.terminate();worker=null;busy.value=false}watch(()=>JSON.stringify(props.scenario),()=>{cancel();rows.value=[];error.value=''});onUnmounted(cancel);
function run(){cancel();rows.value=[];error.value='';try{amounts(props.scenario);const request={hole:props.scenario.hole.filter((c):c is number=>c!==null),board:props.scenario.board.filter((c):c is number=>c!==null),opponents:props.scenario.opponents,samples:10000};validate(request);worker=new Worker();busy.value=true;worker.onmessage=e=>{if(e.data.type==='error'){error.value=e.data.message;cancel()}else{rows.value=e.data.rows;if(e.data.type==='done')cancel()}};worker.onerror=()=>{error.value='比较任务失败';cancel()};worker.postMessage(request)}catch(e){error.value=(e as Error).message;cancel()}}
</script><template><details class="panel"><summary>范围敏感性 · 假设改变后结论如何变化</summary><p class="muted">比较每位对手都使用同一种示例范围的三种场景，不覆盖你的编辑范围。预设不是对玩家的真实推断。每种最多 10,000 次模拟，小规模场景精确计算。</p><button class="secondary full" v-if="!busy" @click="run">比较三种范围假设</button><button class="secondary full" v-else @click="cancel">取消比较</button><p class="error" v-if="error">{{error}}</p><div class="library-item" v-for="row in rows" :key="row.name"><div><strong>{{names[row.name]}} · {{(row.result.equity*100).toFixed(1)}}%</strong><small>{{advise(row.result,scenario).title}}</small><small v-if="row.result.method==='simulation'">抽样标准误差 {{(row.result.se*100).toFixed(2)}} 个百分点</small></div><span v-if="advise(row.result,scenario).ev!==null">EV {{advise(row.result,scenario).ev?.toFixed(2)}}</span></div><p class="muted">场景之间的差异是模型假设差异，不是统计置信区间。</p></details></template>
